import heapq

def solve(nums, k):
    if not nums or k == 0:
        return []
    small = []    # max-heap (negated): lower half, size = ceil(k/2)
    large = []    # min-heap: upper half, size = floor(k/2)
    s_rem = {}    # pending removals from small, keyed by original value
    l_rem = {}    # pending removals from large, keyed by original value
    s_size = l_size = 0

    def _small_top():
        while small and s_rem.get(-small[0], 0):
            v = -small[0]
            s_rem[v] -= 1
            if not s_rem[v]: del s_rem[v]
            heapq.heappop(small)
        return -small[0]

    def _large_top():
        while large and l_rem.get(large[0], 0):
            v = large[0]
            l_rem[v] -= 1
            if not l_rem[v]: del l_rem[v]
            heapq.heappop(large)
        return large[0]

    def _balance():
        nonlocal s_size, l_size
        if s_size > l_size + 1:
            heapq.heappush(large, _small_top())
            heapq.heappop(small)
            l_size += 1; s_size -= 1
        elif l_size > s_size:
            heapq.heappush(small, -_large_top())
            heapq.heappop(large)
            s_size += 1; l_size -= 1

    def _add(val):
        nonlocal s_size, l_size
        if s_size == 0 or val <= _small_top():
            heapq.heappush(small, -val); s_size += 1
        else:
            heapq.heappush(large, val); l_size += 1
        _balance()

    def _remove(val):
        nonlocal s_size, l_size
        if s_size > 0 and val <= _small_top():
            s_rem[val] = s_rem.get(val, 0) + 1; s_size -= 1
        else:
            l_rem[val] = l_rem.get(val, 0) + 1; l_size -= 1
        _balance()

    def _median():
        if s_size == l_size:
            return (_small_top() + _large_top()) / 2.0
        return float(_small_top())

    for val in nums[:k]:
        _add(val)
    result = [_median()]
    for i in range(k, len(nums)):
        _remove(nums[i - k])
        _add(nums[i])
        result.append(_median())
    return result

